import{_ as n}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as r,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"千问术语表","description":"不教操作。只保证「千问」两个字在本站口径一致。","frontmatter":{"title":"千问术语表","description":"不教操作。只保证「千问」两个字在本站口径一致。","domain":"product","tags":["chat"],"role":"glossary"},"headers":[],"relativePath":"zh/products/qwen/qwen-glossary.md","filePath":"zh/products/qwen/qwen-glossary.md","lastUpdated":1787107158000}'),s={name:"zh/products/qwen/qwen-glossary.md"};function t(i,a,l,p,d,h){return r(),e("div",null,[...a[0]||(a[0]=[o(`<h1 id="千问术语表" tabindex="-1">千问术语表 <a class="header-anchor" href="#千问术语表" aria-label="Permalink to &quot;千问术语表&quot;">​</a></h1><p>不教操作。只保证「千问」两个字在本站口径一致。</p><h2 id="概念关系" tabindex="-1">概念关系 <a class="header-anchor" href="#概念关系" aria-label="Permalink to &quot;概念关系&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阿里 / 通义</span></span>
<span class="line"><span>├── 千问（助手产品，本目录）</span></span>
<span class="line"><span>│   ├── 网页 / App / 电脑端</span></span>
<span class="line"><span>│   ├── 办公助理 / 本地电脑 / 定时任务（产品内）</span></span>
<span class="line"><span>│   └── 千问输入法（同厂 App，不拆页）</span></span>
<span class="line"><span>├── 通义实验室（网关：千问 · 万相）</span></span>
<span class="line"><span>│   └── 万相（视觉生成）</span></span>
<span class="line"><span>├── 通义灵码 / Qoder CN（编码助手，#84）</span></span>
<span class="line"><span>├── 阿里云百炼（模型 API 平台，#85）</span></span>
<span class="line"><span>└── 国际站 Qwen</span></span>
<span class="line"><span>    ├── Qwen Studio（chat.qwen.ai）</span></span>
<span class="line"><span>    ├── Qwen Code（qwen.ai/qwencode）</span></span>
<span class="line"><span>    └── Research / 开源（qwenlm.github.io / QwenLM）</span></span></code></pre></div><h2 id="千问" tabindex="-1">千问 <a class="header-anchor" href="#千问" aria-label="Permalink to &quot;千问&quot;">​</a></h2><p><strong>是什么：</strong> 阿里的消费级 AI 助手。官方自称 <strong>阿里官方AI助手</strong>。入口 <a href="https://www.qianwen.com/" target="_blank" rel="noreferrer">qianwen.com</a>。</p><p><strong>为什么单独成页：</strong> 它是面向个人的聊天与办事产品，和实验室网关、编码助手、模型 API 不是同一扇门。</p><p><strong>不是什么：</strong> 不是通义实验室本身，不是通义灵码 / Qoder CN，不是百炼，不是 CLI。</p><h2 id="通义-通义千问" tabindex="-1">通义 / 通义千问 <a class="header-anchor" href="#通义-通义千问" aria-label="Permalink to &quot;通义 / 通义千问&quot;">​</a></h2><p><strong>是什么：</strong> 实验室与旧商店文案里的品牌词。通义实验室页头写「千问 · 万相」。应用宝仍有一段「通义介绍」。</p><p><strong>与千问的区别：</strong> 现行消费助手页的产品名是 <strong>千问</strong>。不要把「通义」当成第二个助手，也不要把旧商店段落实成现行功能。</p><h2 id="通义实验室" tabindex="-1">通义实验室 <a class="header-anchor" href="#通义实验室" aria-label="Permalink to &quot;通义实验室&quot;">​</a></h2><p><strong>是什么：</strong> 模型与应用网关。<a href="https://tongyi.aliyun.com/" target="_blank" rel="noreferrer">tongyi.aliyun.com</a>。页脚「个人应用」指向千问。</p><p><strong>不是什么：</strong> 不是 qianwen.com 的别名。</p><h2 id="万相" tabindex="-1">万相 <a class="header-anchor" href="#万相" aria-label="Permalink to &quot;万相&quot;">​</a></h2><p><strong>是什么：</strong> 通义实验室并列的视觉生成大模型家族。入口 <a href="https://tongyi.aliyun.com/landing?family=wan" target="_blank" rel="noreferrer">landing?family=wan</a>。千问 App 的生视频文案点名 <strong>Wan 2.7</strong>。</p><p><strong>不是什么：</strong> 不是千问里的一个 Tab 名称。本目录不写万相控制台教程。</p><h2 id="通义灵码-qoder-cn" tabindex="-1">通义灵码 / Qoder CN <a class="header-anchor" href="#通义灵码-qoder-cn" aria-label="Permalink to &quot;通义灵码 / Qoder CN&quot;">​</a></h2><p><strong>是什么：</strong> 阿里云编码助手。官方仍保有 <a href="https://lingma.aliyun.com/" target="_blank" rel="noreferrer">lingma.aliyun.com</a>；产品页与帮助中心同时使用 <strong>Qoder CN</strong>（<a href="https://qoder.com.cn/" target="_blank" rel="noreferrer">qoder.com.cn</a>，帮助中心写 2026-05-20 由通义灵码更名）。本站 #84。</p><p><strong>与千问「代码」的区别：</strong> 千问官方原文是对话里生成 / 检查小程序、网页、小游戏、SQL。Qoder CN 才是 IDE / CLI 编码产品。本目录只这一行。</p><h2 id="阿里云百炼" tabindex="-1">阿里云百炼 <a class="header-anchor" href="#阿里云百炼" aria-label="Permalink to &quot;阿里云百炼&quot;">​</a></h2><p><strong>是什么：</strong> 大模型服务与应用平台。<a href="https://www.aliyun.com/product/bailian" target="_blank" rel="noreferrer">aliyun.com/product/bailian</a>。本站 #85。</p><p><strong>与千问「API 服务」的区别：</strong> 首页顶栏有 <strong>API 服务</strong> 按钮。调用模型、买 Token Plan 走百炼，不要在千问教程里教 <code>API Key</code>。</p><h2 id="qwen-studio" tabindex="-1">Qwen Studio <a class="header-anchor" href="#qwen-studio" aria-label="Permalink to &quot;Qwen Studio&quot;">​</a></h2><p><strong>是什么：</strong> 国际站助手。 <a href="https://chat.qwen.ai/" target="_blank" rel="noreferrer">chat.qwen.ai</a> 与 <a href="https://qwen.ai/" target="_blank" rel="noreferrer">qwen.ai</a> 的页面名就是 <strong>Qwen Studio</strong>。qwen.ai 原文：「an AI assistant for everyone, powered by the Qwen series models」。</p><p><strong>不是什么：</strong> 不是「千问」二字的官方英译产品名，也不是 qianwen.com 的自动镜像。本目录不写安装。</p><h2 id="qwen-code" tabindex="-1">Qwen Code <a class="header-anchor" href="#qwen-code" aria-label="Permalink to &quot;Qwen Code&quot;">​</a></h2><p><strong>是什么：</strong> 国际站终端编码 Agent。<a href="https://qwen.ai/qwencode" target="_blank" rel="noreferrer">qwen.ai/qwencode</a> 原文：open-source AI agent for the terminal。</p><p><strong>不是什么：</strong> 不是千问首页的「代码」按钮。</p><h2 id="办公助理-本地电脑" tabindex="-1">办公助理 / 本地电脑 <a class="header-anchor" href="#办公助理-本地电脑" aria-label="Permalink to &quot;办公助理 / 本地电脑&quot;">​</a></h2><p><strong>是什么：</strong> qianwen.com 首页上的模式。横幅写办公助理可解锁本地任务、手机远程操控、技能与连接器。</p><p><strong>不是什么：</strong> 不是 QoderWork，也不是帮助中心「千问办公 (QwenWork)」那条产品线。后者属 #84 周边，本目录不写安装。</p><h2 id="千问输入法" tabindex="-1">千问输入法 <a class="header-anchor" href="#千问输入法" aria-label="Permalink to &quot;千问输入法&quot;">​</a></h2><p><strong>是什么：</strong> 首页横幅宣布的输入法 App。应用宝包名 <code>com.qianwen.ime</code>。</p><p><strong>不是什么：</strong> 不是第二个聊天助手，不单独开手册。</p><h2 id="交付形态-协议里的词" tabindex="-1">交付形态（协议里的词） <a class="header-anchor" href="#交付形态-协议里的词" aria-label="Permalink to &quot;交付形态（协议里的词）&quot;">​</a></h2><p>用户服务协议把千问产品写成：网站 <code>qianwen.com</code>、网页、客户端（iOS、Android、Windows、Mac、HarmonyOS）、浏览器插件、小程序、H5，以及以后可能出现的载体。前几个有公开网页 / 商店入口；插件 / 小程序 / HarmonyOS 助手安装页 2026-08-19 没有找到，术语上承认名字，教程里不写步骤。</p><h2 id="禁止写进正文的叫法" tabindex="-1">禁止写进正文的叫法 <a class="header-anchor" href="#禁止写进正文的叫法" aria-label="Permalink to &quot;禁止写进正文的叫法&quot;">​</a></h2><ul><li>「千问 CLI」「Qwen IDE 插件」「千问国际版」——官方页没有这些产品名（国际站写的是 Qwen Studio）。</li><li>把百炼 Token Plan 或 Coding Plan 叫成「千问会员价」。</li><li>把商店用户评论里的额度、外卖减免、默认模型当成规格。</li><li>把淘宝 / 钉钉 / ECS 写成千问家族产品。</li></ul>`,39)])])}const w=n(s,[["render",t]]);export{m as __pageData,w as default};
